c076.try_sql:
-- System: just the action's name; object: always a specific object (TABLE_NAME)
SELECT privilege FROM user_sys_privs ORDER BY privilege;
SELECT owner, table_name, privilege FROM user_tab_privs;

c077.try_sql:
-- System privileges have an ADMIN_OPTION column, object privileges a GRANTABLE column (GRANT OPTION)
SELECT privilege, admin_option FROM user_sys_privs ORDER BY privilege;
SELECT table_name, privilege, grantable FROM user_tab_privs;

c078.try_sql:
-- UPDATE can be granted on a column, SELECT on a column cannot (ORA-00969)
CREATE TABLE lab_c078_emp AS SELECT employee_id, last_name, salary FROM employees;
GRANT UPDATE (salary) ON lab_c078_emp TO PUBLIC;
GRANT SELECT (salary) ON lab_c078_emp TO PUBLIC;
SELECT grantee, table_name, column_name, privilege FROM user_col_privs_made WHERE table_name = 'LAB_C078_EMP';

c700.try_sql:
-- UPDATE granted on two columns: you cannot revoke it from one (ORA-01750), only from the whole table
CREATE TABLE lab_c700_t (a NUMBER, b NUMBER);
GRANT UPDATE (a, b) ON lab_c700_t TO PUBLIC;
REVOKE UPDATE (a) ON lab_c700_t FROM PUBLIC;
SELECT column_name, privilege FROM user_col_privs_made WHERE table_name = 'LAB_C700_T';
REVOKE UPDATE ON lab_c700_t FROM PUBLIC;
SELECT COUNT(*) AS ile FROM user_col_privs_made WHERE table_name = 'LAB_C700_T';

c701.try_sql:
-- A sequence: only SELECT and ALTER (ORA-02205); a view: SELECT and DML, but not ALTER (ORA-02204)
CREATE SEQUENCE lab_c701_s;
GRANT SELECT, ALTER ON lab_c701_s TO PUBLIC;
GRANT INSERT ON lab_c701_s TO PUBLIC;
CREATE VIEW lab_c701_v AS SELECT employee_id, last_name FROM employees;
GRANT SELECT, INSERT, UPDATE, DELETE ON lab_c701_v TO PUBLIC;
GRANT ALTER ON lab_c701_v TO PUBLIC;
SELECT table_name, privilege FROM user_tab_privs_made WHERE table_name IN ('LAB_C701_S', 'LAB_C701_V') ORDER BY 1, 2;

c702.try_sql:
-- Compare: SESSION_PRIVS (also from roles) and USER_SYS_PRIVS (only direct grants, with ADMIN_OPTION)
SELECT privilege FROM session_privs ORDER BY privilege;
SELECT privilege, admin_option FROM user_sys_privs ORDER BY privilege;
SELECT role FROM session_roles;

c704.try_sql:
-- WITH GRANT OPTION for PUBLIC works, for a role it does not (ORA-01926)
CREATE TABLE lab_c704_t (n NUMBER);
GRANT SELECT ON lab_c704_t TO PUBLIC WITH GRANT OPTION;
GRANT SELECT ON lab_c704_t TO resource WITH GRANT OPTION;
SELECT grantee, privilege, grantable FROM user_tab_privs_made WHERE table_name = 'LAB_C704_T';

c705.try_sql:
-- The grant disappears with the table; a new table with the same name has no grants
CREATE TABLE lab_c705_t (n NUMBER);
GRANT SELECT ON lab_c705_t TO PUBLIC;
SELECT grantee, privilege FROM user_tab_privs_made WHERE table_name = 'LAB_C705_T';
DROP TABLE lab_c705_t PURGE;
CREATE TABLE lab_c705_t (n NUMBER);
SELECT COUNT(*) AS nadania FROM user_tab_privs_made WHERE table_name = 'LAB_C705_T';

c1700.try_sql:
-- A GRANT on a synonym is recorded on the table it points to
CREATE TABLE lab_c1700_t (n NUMBER);
CREATE SYNONYM lab_c1700_s FOR lab_c1700_t;
GRANT SELECT ON lab_c1700_s TO PUBLIC;
SELECT grantee, table_name, privilege FROM user_tab_privs_made WHERE table_name IN ('LAB_C1700_T', 'LAB_C1700_S');

c1701.try_sql:
-- A user that does not exist: ORA-01917, nothing is recorded; PUBLIC works
CREATE TABLE lab_c1701_t (n NUMBER);
GRANT SELECT ON lab_c1701_t TO lab_c1701_nobody;
GRANT SELECT ON lab_c1701_t TO PUBLIC;
SELECT grantee, privilege FROM user_tab_privs_made WHERE table_name = 'LAB_C1701_T';

c1702.try_sql:
-- Only SELECT was granted: REVOKE SELECT, INSERT raises ORA-01927 and revokes nothing; REVOKE ALL works
CREATE TABLE lab_c1702_t (n NUMBER);
GRANT SELECT ON lab_c1702_t TO PUBLIC;
REVOKE SELECT, INSERT ON lab_c1702_t FROM PUBLIC;
SELECT privilege FROM user_tab_privs_made WHERE table_name = 'LAB_C1702_T';
REVOKE ALL ON lab_c1702_t FROM PUBLIC;
SELECT COUNT(*) AS nadania FROM user_tab_privs_made WHERE table_name = 'LAB_C1702_T';

c1703.try_sql:
-- No privilege at all: the table "does not exist" (ORA-00942)
SELECT COUNT(*) FROM sys.obj$;
-- You have SELECT on SYS.DUAL, but not UPDATE: ORA-01031 (ORA-41900 in 23ai)
UPDATE sys.dual SET dummy = 'Y';

c1704.try_sql:
-- PUBLIC has READ on SYS.SYSTEM_PRIVILEGE_MAP without GRANT OPTION: the view works, but it cannot be granted further (ORA-01720)
SELECT privilege, grantable FROM all_tab_privs WHERE table_schema = 'SYS' AND table_name = 'SYSTEM_PRIVILEGE_MAP' AND grantee = 'PUBLIC';
CREATE VIEW lab_c1704_v AS SELECT name FROM sys.system_privilege_map;
SELECT COUNT(*) AS ile FROM lab_c1704_v;
GRANT SELECT ON lab_c1704_v TO PUBLIC;

c1708.try_sql:
-- Which system privileges the CONNECT and RESOURCE roles give (only roles you hold are visible)
SELECT role, privilege FROM role_sys_privs WHERE role IN ('CONNECT', 'RESOURCE') ORDER BY role, privilege;
SELECT role FROM session_roles;
